db.execute('pragma busy_timeout=10000');db.set_progress_handler(lambda:int(time.monotonic()-started>1500),10000)
facts={n:(name,t) for n,name,t in db.execute("select norad,name,object_type from object where norad%25=0 and object_type in ('DEBRIS','ROCKET BODY','PAYLOAD') order by norad")}
cat=oc.load_catalog(Path('/home/sdegan/space-teaching-aid/public/data'));expect=oc.Expectations.load()
