import json, collections
from pathlib import Path
root=Path('/tmp/orbit-phase2b')
bands=['0-1','1-5','5-15','15-30','30-60','60-90','90-120','120-180']
def band(x):
    return next(label for edge,label in zip([1,5,15,30,60,90,120,181],bands) if x<edge)
def count(events, inc_key):
    table={g:{b:collections.Counter() for b in bands} for g in ['passive','payload']}
    sigs=collections.Counter()
    for e in events:
        table[e['group']][band(e[inc_key])][e['channelCombination']]+=1
        if e[inc_key]>=30 and e['channelCombination']=='inclination':sigs[e['signature']]+=1
    return table,sigs
p=root/'published-inclination.json'
if p.exists():
    table,sigs=count(json.loads(p.read_text()),'inclinationDeg')
    print('PUBLISHED',json.dumps(table,indent=2)); print('PUBLISHED HIGH I ALONE SIGNATURES',dict(sigs))
p=root/'archive-result.json'
if p.exists():
    a=json.loads(p.read_text());table,sigs=count(a['events'],'inclination'); print('SAMPLE',json.dumps(table,indent=2))
    stats={}
    for g in table:
        counts=sum((table[g][b] for b in bands[4:]),collections.Counter())
        exposure=sum(a['histograms'][g+'Intervals']['inclination'].get(b,0) for b in bands[4:])
        stats[g]={'inclinationFlags':sum(counts.values()),'alone':counts['inclination'],'aloneFraction':counts['inclination']/sum(counts.values()),'intervals':exposure,'alonePer1000':1000*counts['inclination']/exposure}
    ratio=stats['payload']['alonePer1000']/stats['passive']['alonePer1000']
    print('GATE',stats,'ratio',ratio,'PASS',stats['passive']['aloneFraction']>=.6 and ratio<=1.5)
    (root/'gate.json').write_text(json.dumps({'stats':stats,'ratio':ratio,'pass':stats['passive']['aloneFraction']>=.6 and ratio<=1.5,'table':table},indent=2))
